impl ByCasesStmt {
    pub fn ir(&self) -> StmtIR {
        let mut out = String::new();
        let question_goals: Vec<_> = self
            .then_facts
            .iter()
            .map(|fact| format!("{} {}", QUESTION_GOAL, fact.ir()))
            .collect();
        let mut case_blocks = Vec::new();
        for ((case, proof), impossible_fact) in self
            .cases
            .iter()
            .zip(self.proofs.iter())
            .zip(self.impossible_facts.iter())
        {
            if let Some(impossible_fact) = impossible_fact {
                let case_header = format!(
                    "{} {}{}",
                    indent!(CASE, 1),
                    case.ir(),
                    COLON
                );
                let impossible_line = format!(
                    "{} {}",
                    indent!(IMPOSSIBLE, 2),
                    impossible_fact.ir()
                );
                if proof.is_empty() {
                    case_blocks.push(format!("{}\n{}", case_header, impossible_line));
                } else {
                    case_blocks.push(format!(
                        "{}\n{}\n{}",
                        case_header,
                        indent!(
                            &proof
                                .iter()
                                .map(|s| s.ir())
                                .collect::<Vec<_>>()
                                .join(
                                    "
"
                                ),
                            2
                        ),
                        impossible_line
                    ));
                }
            } else if proof.is_empty() {
                case_blocks.push(format!(
                    "{} {}",
                    indent!(CASE, 1),
                    case.ir()
                ));
            } else {
                case_blocks.push(format!(
                    "{} {}{}\n{}",
                    indent!(CASE, 1),
                    case.ir(),
                    COLON,
                    indent!(
                        &proof
                            .iter()
                            .map(|s| s.ir())
                            .collect::<Vec<_>>()
                            .join(
                                "
"
                            ),
                        2
                    )
                ));
            }
        }
        out.push_str(&format!(
            "{} {}{}\n{}\n{}",
            BY,
            CASES,
            COLON,
            indent!(
                &question_goals.join(
                    "
"
                ),
                1
            ),
            case_blocks.join(
                "
"
            )
        ));

        StmtIR(out)
    }
    impl_display_pair!();
}

